  ('90000001-0000-4000-8000-000000000006', '30000001-0000-4000-8000-000000000004', 'แจ้งซ่อมใหม่ RR-2026-011',     'พล-0044 ผ้าเบรกสึกหรอ ได้ยินเสียงเอี๊ยด ต้องเปลี่ยนผ้าเบรก',              'info',    now() - interval '6 hours'),
